function maxSubArrayBrute(nums) {
  let maxSum = -Infinity;
  for (let i = 0; i < nums.length; i++) {
    let currSum = 0;
    for (let j = i; j < nums.length; j++) {
      currSum += nums[j];           // sum of nums[i..j]
      maxSum = Math.max(maxSum, currSum);
    }
  }
  return maxSum;
}

